#!/usr/bin/env python3
"""Verify that the public article protocol and its reference run stay aligned."""

from __future__ import annotations

import argparse
import csv
import hashlib
import json
from pathlib import Path
from typing import Any

from tangle_sim.audit import AuditError, audit_run
from tangle_sim.config import load_config, scenario_alpha, scenario_private_build_seconds


