# Updated only when the frozen v15 report is deliberately regenerated by the
# current reporting code.  Semantic checks below remain mandatory as a hash
# alone does not explain what is being frozen.
EXPECTED_SUMMARY_SHA256 = "15a50adb74eaa1240c2af42b9d207c2275a98a4a0f7818411522a1c8f44212ab"

