EXPECTED_ATTACK_EVENTS = {
    ("PACTCare", "urts"): 10,
    ("PACTCare", "mcmc"): 10,
    ("PACTCare", "sb_wrw"): 4,
    ("TLIP", "urts"): 10,
    ("TLIP", "mcmc"): 10,
    ("TLIP", "sb_wrw"): 2,
    ("ElaadNL", "urts"): 10,
    ("ElaadNL", "mcmc"): 10,
    ("ElaadNL", "sb_wrw"): 8,
}


class AlignmentError(RuntimeError):
    pass


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def _read_csv(path: Path) -> list[dict[str, str]]:
    with path.open(encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle))


def verify_alignment(config_path: Path, results_dir: Path) -> dict[str, Any]:
    config = load_config(config_path)
    errors: list[str] = []

    def require(condition: bool, message: str) -> None:
        if not condition:
            errors.append(message)

    require(config.sha256() == EXPECTED_CONFIG_SHA256, "canonical config hash changed")
    require(config.replicates == 10, "article requires 10 replicates")
    require(config.root_seed == 20250701, "canonical root seed changed")
    require(
        config.raw["experiment_id"] == "v15-progressive-stress-to-failure",
        "article result experiment changed",
    )
    require(
        config.raw["algorithms"]["sb_wrw"]["conformance"] == "operational_reproduction",
        "SB-WRW must remain labelled as an operational reproduction",
    )
    for scenario, expected in {
        "PACTCare": 2.25,
        "TLIP": 0.1,
        "ElaadNL": 0.1,
    }.items():
        require(scenario_alpha(config, scenario) == expected, f"alpha mismatch: {scenario}")

    simulation = config.raw["simulation"]
    for field, expected in {
        "warmup_seconds": 5.0,
        "measurement_seconds": 25.0,
        "drain_seconds": 5.0,
        "abandonment_age_seconds": 5.0,
    }.items():
        require(float(simulation[field]) == expected, f"simulation.{field} changed")

    attack = config.raw["attack"]
    require(float(attack["attacker_rate_fraction"]) == 0.36, "initial attacker share changed")
    require(
        attack["attacker_rate_fraction_schedule"] == [
            {"after_seconds": 60.0, "fraction": 0.70},
            {"after_seconds": 75.0, "fraction": 0.85},
        ],
        "progressive attack schedule changed",
    )
    require(float(attack["attack_observation_seconds"]) == 110.0, "attack horizon changed")
    require(float(attack["fraud_confidence_threshold"]) == 0.95, "fraud threshold changed")
    require(float(attack["confidence_stability_seconds"]) == 2.0, "stability window changed")
    require(float(attack["confidence_check_interval_seconds"]) == 0.5, "check interval changed")
    for scenario, expected in {"PACTCare": 5.0, "TLIP": 15.0, "ElaadNL": 15.0}.items():
        require(
            scenario_private_build_seconds(config, scenario) == expected,
            f"private build duration changed: {scenario}",
        )

    manifest_path = results_dir / "manifest.json"
    require(manifest_path.is_file(), "reference manifest is missing")
    if manifest_path.is_file():
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        require(manifest.get("config_sha256") == config.sha256(), "result/config hash mismatch")
        require(manifest.get("replicates") == 10, "reference run does not contain 10 replicates")
        require(
            manifest.get("sb_wrw_conformance") == "operational_reproduction",
            "reference result mislabels SB-WRW conformance",
        )

    summary_path = results_dir / "summary" / "metrics_summary.csv"
    require(summary_path.is_file(), "reference summary is missing")
    # The preserved public reference is bitwise frozen. Fresh reproductions
    # are audited semantically because volatile platform/library details can
    # prevent byte-for-byte equality across environments.
    if summary_path.is_file() and results_dir.name == "v15":
        require(_sha256(summary_path) == EXPECTED_SUMMARY_SHA256, "reference summary hash changed")
    if summary_path.is_file():
        actual_estimates = {
            (row["scenario"], row["algorithm"], row["metric"]): float(row["estimate"])
            for row in _read_csv(summary_path)
            if row["metric"] in {
                "confirmation_rate_percent",
                "abandonment_percent",
                "fraud_rmst_seconds",
            }
        }
        require(
            set(actual_estimates) == set(EXPECTED_ARTICLE_ESTIMATES),
            "primary article metric cells changed",
        )
        for key, expected in EXPECTED_ARTICLE_ESTIMATES.items():
            actual = actual_estimates.get(key)
            require(
                actual is not None and abs(actual - expected) <= 0.005,
                f"article estimate mismatch: {key}: {actual} != {expected}",
            )

    attack_path = results_dir / "raw" / "attack_runs.csv"
    require(attack_path.is_file(), "reference attack runs are missing")
    if attack_path.is_file():
        event_counts = {key: 0 for key in EXPECTED_ATTACK_EVENTS}
        for row in _read_csv(attack_path):
            key = (row["scenario"], row["algorithm"])
            if row["event_observed"].lower() in {"true", "1"}:
                event_counts[key] += 1
        require(event_counts == EXPECTED_ATTACK_EVENTS, "attack event counts changed")

    figure_path = results_dir / "plots" / "graficos_combinados.png"
    require(figure_path.is_file() and figure_path.stat().st_size > 0, "manuscript figure is missing")

    precision_path = results_dir / "summary" / "precision_assessment.csv"
    require(precision_path.is_file(), "precision assessment is missing")
    precision_counts = {"met": 0, "not_met": 0, "not_assessable_all_censored": 0}
    if precision_path.is_file():
        for row in _read_csv(precision_path):
            status = row["assessment_status"]
            if status in precision_counts:
                precision_counts[status] += 1
        require(
            precision_counts == {
                "met": 20,
                "not_met": 7,
                "not_assessable_all_censored": 0,
            },
            "precision classification changed",
        )

    audit: dict[str, Any] | None = None
    if not errors:
        try:
            audit = audit_run(results_dir, write=False)
        except AuditError as exc:
            require(False, f"reference audit failed: {exc}")
        if audit is not None:
            require(audit["valid"], "reference audit failed")
            require(audit["row_counts"] == {"benign": 90, "attack": 90, "summary": 45}, "row counts changed")

    if errors:
        raise AlignmentError("; ".join(errors))

    return {
        "aligned": True,
        "config": str(config_path),
        "results": str(results_dir),
        "config_sha256": config.sha256(),
        "summary_sha256": _sha256(summary_path),
        "row_counts": audit["row_counts"] if audit else {},
        "precision": precision_counts,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=Path, default=Path("configs/article.yaml"))
    parser.add_argument("--results", type=Path, default=Path("results/v15"))
    args = parser.parse_args()
    try:
        report = verify_alignment(args.config, args.results)
    except AlignmentError as exc:
        print(json.dumps({"aligned": False, "error": str(exc)}, ensure_ascii=False, indent=2))
        return 2
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
